// Generated from the files in `schemas/` by `tests/build.mjs --schemas`.
// Edit the YAML there, not this file: two copies that can drift are one copy
// too many, and the check in the test suite fails if they do.

export const STARTER_SCHEMAS: Record<string, string> = {
	"core.yaml": "# World Engine — core entity types.\n#\n# Every schema here is a plain YAML mapping of `TypeName: definition`. Edit it,\n# commit it, delete it: nothing in this file is generated, and the plugin reads\n# it fresh on every \"Reload schemas\".\n#\n# `additionalProperties: true` is set on all of them on purpose. These schemas\n# arrive in a vault that already has notes in it, and a schema that flagged every\n# undeclared property would light up the whole folder on the day it was created.\n# Set it to false on a type once that type is actually under control.\n\nentity:\n  description: Shared base for every world entity. Not used directly.\n  version: 1\n  additionalProperties: true\n  required:\n    - title\n  properties:\n    title:\n      type: string\n      description: Display name. Falls back to the filename when absent.\n    id:\n      type: string\n      description: Stable identifier, unique across the vault.\n      pattern: \"[a-z0-9][a-z0-9-]*\"\n    canon_status:\n      type: enum\n      values: [idea, draft, provisional, canon, retired, non-canon]\n      default: draft\n    tags:\n      type: list\n      items: string\n    summary:\n      type: string\n\ncharacter:\n  extends: entity\n  folder: Characters\n  description: A person, creature or intelligence that acts in the story.\n  version: 1\n  additionalProperties: true\n  required:\n    - status\n  properties:\n    status:\n      type: enum\n      values: [alive, dead, unknown]\n      default: alive\n    species:\n      type: string\n    age:\n      type: number\n      min: 0\n    born:\n      type: date\n    died:\n      type: date\n    faction:\n      type: link\n  relationships:\n    knows:\n      target: character\n      inverse: knows\n      description: Symmetric acquaintance.\n    parent_of:\n      target: character\n      inverse: child_of\n    child_of:\n      target: character\n      inverse: parent_of\n    member_of:\n      target: faction\n      inverse: has_member\n    possesses:\n      target: item\n      inverse: possessed_by\n    located_at:\n      target: location\n      inverse: houses\n      cardinality: one\n\nlocation:\n  extends: entity\n  folder: Locations\n  description: A place. Anything from a room to a continent.\n  version: 1\n  additionalProperties: true\n  properties:\n    region:\n      type: string\n    population:\n      type: integer\n      min: 0\n  relationships:\n    part_of:\n      target: location\n      inverse: contains\n      cardinality: one\n    contains:\n      target: location\n      inverse: part_of\n    houses:\n      target: character\n      inverse: located_at\n\nfaction:\n  extends: entity\n  folder: Factions\n  description: An organisation, house, order or cult.\n  version: 1\n  additionalProperties: true\n  properties:\n    founded:\n      type: date\n    status:\n      type: enum\n      values: [active, dormant, destroyed, unknown]\n  relationships:\n    has_member:\n      target: character\n      inverse: member_of\n    allied_with:\n      target: faction\n      inverse: allied_with\n    at_war_with:\n      target: faction\n      inverse: at_war_with\n    based_at:\n      target: location\n      cardinality: one\n\nitem:\n  extends: entity\n  folder: Items\n  description: An object with a history worth tracking.\n  version: 1\n  additionalProperties: true\n  properties:\n    rarity:\n      type: string\n  relationships:\n    possessed_by:\n      target: character\n      inverse: possesses\n      cardinality: one\n    created_by:\n      target: character\n    kept_at:\n      target: location\n      cardinality: one\n\nevent:\n  extends: entity\n  folder: Events\n  description: Something that happened at a point or range in time.\n  version: 1\n  additionalProperties: true\n  required:\n    - date\n  properties:\n    date:\n      type: date\n      description: Start of the event. `YYYY-MM-DD`, `YYYY-MM` or a bare year.\n    end_date:\n      type: date\n    participants:\n      type: links\n    location:\n      type: link\n  relationships:\n    participants:\n      target: character\n      inverse: participated_in\n    location:\n      target: location\n    occurred_before:\n      target: event\n      inverse: occurred_after\n    occurred_after:\n      target: event\n      inverse: occurred_before\n    caused_by:\n      target: event\n      inverse: caused\n",
	"story.yaml": "# World Engine — story-side types.\n#\n# Chapters, books and story threads. The thread tracker itself (§16) is Phase 2;\n# what is here is the schema, so threads written now validate and are indexed\n# from the day the tracker arrives rather than needing a migration.\n\nbook:\n  extends: entity\n  folder: Story/Books\n  version: 1\n  additionalProperties: true\n  properties:\n    status:\n      type: enum\n      values: [planned, drafting, revising, complete]\n      default: planned\n    word_target:\n      type: integer\n      min: 0\n\nchapter:\n  extends: entity\n  folder: Story/Chapters\n  version: 1\n  additionalProperties: true\n  required:\n    - status\n  properties:\n    number:\n      type: number\n    status:\n      type: enum\n      values: [outline, draft, revised, final]\n      default: draft\n    pov:\n      type: link\n    word_count:\n      type: integer\n      min: 0\n  relationships:\n    part_of:\n      target: book\n      inverse: contains\n      cardinality: one\n    pov:\n      target: character\n    features:\n      target: character\n      inverse: appears_in\n\nstory_thread:\n  extends: entity\n  folder: Story/Threads\n  description: An unresolved narrative element. Open until something closes it.\n  version: 1\n  additionalProperties: true\n  required:\n    - status\n  properties:\n    status:\n      type: enum\n      values: [open, resolved, abandoned]\n      default: open\n    priority:\n      type: enum\n      values: [low, medium, high]\n    introduced:\n      type: link\n    last_referenced:\n      type: link\n    resolved_in:\n      type: link\n  relationships:\n    introduced:\n      target: chapter\n    last_referenced:\n      target: chapter\n    resolved_in:\n      target: chapter\n    concerns:\n      target: character\n",
};
